#!/usr/bin/env bash
HEXTUNNEL_SECRETS_FILE="${HEXTUNNEL_SECRETS_FILE:-/etc/hextunnel/secrets.env}"
load_hextunnel_secrets() { ensure_dir 700 "$HEXTUNNEL_ETC"; if [[ -f "$HEXTUNNEL_SECRETS_FILE" ]]; then local mode; mode="$(stat -c '%a' "$HEXTUNNEL_SECRETS_FILE" 2>/dev/null || printf 000)"; [[ "$mode" == 600 || "$mode" == 400 ]] || die "$HEXTUNNEL_SECRETS_FILE debe tener permisos 600 o 400."; source "$HEXTUNNEL_SECRETS_FILE"; fi; HEXTUNNEL_TELEGRAM_CHAT_ID="${HEXTUNNEL_TELEGRAM_CHAT_ID:-}"; HEXTUNNEL_TELEGRAM_BOT_TOKEN="${HEXTUNNEL_TELEGRAM_BOT_TOKEN:-}"; export HEXTUNNEL_TELEGRAM_CHAT_ID HEXTUNNEL_TELEGRAM_BOT_TOKEN; }
secret_get_or_create() { local name="$1" length="${2:-32}" current; current="${!name:-}"; if [[ -n "$current" ]]; then printf '%s' "$current"; return 0; fi; ensure_dir 700 "$HEXTUNNEL_ETC"; current="$(random_secret "$length")"; if [[ "${HEXTUNNEL_DRY_RUN:-0}" != 1 ]]; then touch "$HEXTUNNEL_SECRETS_FILE"; chmod 600 "$HEXTUNNEL_SECRETS_FILE"; printf '%s=%q\n' "$name" "$current" >> "$HEXTUNNEL_SECRETS_FILE"; fi; printf -v "$name" '%s' "$current"; export "$name"; printf '%s' "$current"; }
telegram_notify() { local message="$1"; [[ -n "${HEXTUNNEL_TELEGRAM_CHAT_ID:-}" && -n "${HEXTUNNEL_TELEGRAM_BOT_TOKEN:-}" ]] || return 0; curl -fsS --max-time 10 --retry 2 --data-urlencode "chat_id=$HEXTUNNEL_TELEGRAM_CHAT_ID" --data-urlencode "text=$message" "https://api.telegram.org/bot${HEXTUNNEL_TELEGRAM_BOT_TOKEN}/sendMessage" >/dev/null || log_warn "No se pudo enviar la notificación de Telegram."; }
